{
  "avaliacoes": [
    {
      "id": "Edba01c29fe623019",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A verificação da integridade de barreiras por auditorias é apresentada como útil, mas limitada a um retrato do momento da auditoria; para cada operação, o texto recomenda o uso de checklists pré-operacionais alinhados às barreiras de controle definidas nos bow ties.",
          "trechos": [
            "Edba01c29fe623019:0:699",
            "Edba01c29fe623019:699:1397",
            "Edba01c29fe623019:2092:2329"
          ],
          "condicoes": [
            "aplicado ao acompanhamento da integridade de barreiras em atividades operacionais",
            "os checklists devem estar alinhados às barreiras de controle estabelecidas nos bow ties"
          ],
          "limites": [
            "a auditoria não garante por si só a integridade futura das barreiras",
            "a fonte não define critérios quantitativos de aceitação, desempenho ou frequência"
          ]
        },
        {
          "proposicao": "Safety cases são descritos como instrumentos para demonstrar que operações serão conduzidas com segurança, que riscos são conhecidos e reduzidos ao nível ALARP, além de disseminar conhecimento sobre riscos e perigos na frente operacional.",
          "trechos": [
            "Edba01c29fe623019:699:1397",
            "Edba01c29fe623019:1397:2092"
          ],
          "condicoes": [
            "na fonte, o uso é contextualizado em indústria do petróleo e também mencionado em outras áreas"
          ],
          "limites": [
            "a fonte apresenta objetivo e utilidade do safety case, não um requisito brasileiro",
            "não traz método detalhado para demonstrar ALARP"
          ]
        },
        {
          "proposicao": "O texto afirma que safety cases só são efetivos quando combinados com um sistema de gestão robusto e adequado, e recomenda sua implementação associada à atividade de construção de poços offshore e à gestão das contratadas.",
          "trechos": [
            "Edba01c29fe623019:1397:2092"
          ],
          "condicoes": [
            "a efetividade é condicionada à combinação com sistema de gestão robusto e adequado"
          ],
          "limites": [
            "a recomendação está voltada à construção de poços offshore, não especificamente a FPSOs",
            "não detalha critérios de robustez do sistema de gestão"
          ]
        }
      ]
    },
    {
      "id": "E89a6a125fdc8cd21",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Nos bow ties voltados à demonstração de riscos em ALARP, devem ser identificados e descritos os SCEs, e a cada elemento crítico de segurança é atribuído um resultado esperado de desempenho, denominado Performance Standard, para orientar a força de trabalho.",
          "trechos": [
            "E89a6a125fdc8cd21:0:692"
          ],
          "condicoes": [
            "aplicado ao uso de bow ties para demonstrar controle de risco em nível ALARP"
          ],
          "limites": [
            "a fonte não informa métricas, faixas ou parâmetros numéricos desses padrões de desempenho"
          ]
        },
        {
          "proposicao": "Quando um elemento crítico de segurança fica fora dos parâmetros pré-estabelecidos, a continuidade operacional é condicionada à aprovação de autoridade técnica, que define medidas mitigadoras até o restabelecimento do Performance Standard; em alguns casos pode haver suspensão de atividades.",
          "trechos": [
            "E89a6a125fdc8cd21:0:692",
            "E89a6a125fdc8cd21:692:1391"
          ],
          "condicoes": [
            "aplica-se quando o SCE não atende aos parâmetros pré-estabelecidos",
            "a avaliação é documentada via gestão de mudanças"
          ],
          "limites": [
            "a fonte não estabelece quais desvios exigem suspensão nem o processo decisório completo",
            "o relato é apresentado como prática descrita na literatura, não como regra geral"
          ]
        },
        {
          "proposicao": "A metodologia bow tie é apresentada como ferramenta de fácil visualização e útil para monitorar a integridade de barreiras preventivas e mitigadoras.",
          "trechos": [
            "E89a6a125fdc8cd21:692:1391"
          ],
          "condicoes": [
            "no contexto de ferramentas e metodologias usadas ao longo do ciclo de vida de empreendimentos"
          ],
          "limites": [
            "a fonte não compara eficácia com outras técnicas de análise de risco",
            "não detalha critérios de seleção das barreiras"
          ]
        }
      ]
    },
    {
      "id": "Ef2b308401839de76",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A Metodologia de Diagnóstico de Segurança Operacional proposta adota conceitos de Bow Tie e AHP para avaliar risco de processo em instalações produtoras de petróleo na fase de operação, com foco na integridade de barreiras dos cenários monitorados.",
          "trechos": [
            "Ef2b308401839de76:0:697",
            "Ef2b308401839de76:697:1394"
          ],
          "condicoes": [
            "aplicada à fase de operação de instalações produtoras de petróleo"
          ],
          "limites": [
            "trata-se de proposta metodológica, não de norma",
            "a fonte não demonstra aplicabilidade universal a FPSOs específicos"
          ]
        },
        {
          "proposicao": "A metodologia é estruturada em quatro etapas: seleção dos cenários a monitorar, identificação qualitativa de ameaças por Bow Tie, hierarquização dos eventos por AHP e aplicação do conceito ALARP para eliminação, contingenciamento ou mitigação de novas ameaças e consequências.",
          "trechos": [
            "Ef2b308401839de76:697:1394",
            "Ef2b308401839de76:1394:2094"
          ],
          "condicoes": [
            "depende de sistema informatizado para permitir a aplicação da metodologia"
          ],
          "limites": [
            "a fonte não define critérios objetivos para escolher entre eliminar, contingenciar ou mitigar",
            "não apresenta limiares de tolerabilidade"
          ]
        },
        {
          "proposicao": "O processo de aquisição de dados da metodologia usa integração automática de sistemas de operação, manutenção, inspeção e segurança.",
          "trechos": [
            "Ef2b308401839de76:2094:2308"
          ],
          "condicoes": [
            "vinculado ao sistema informatizado desenvolvido para a metodologia"
          ],
          "limites": [
            "a fonte não especifica qualidade, completude ou validação desses dados"
          ]
        }
      ]
    },
    {
      "id": "E4d70a1f5507e385e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O gerenciamento de riscos é descrito como uso de múltiplas barreiras de segurança que devem operar de maneira independente, para evitar que uma falha comum afete várias barreiras.",
          "trechos": [
            "E4d70a1f5507e385e:0:696",
            "E4d70a1f5507e385e:2081:2272"
          ],
          "condicoes": [
            "aplicado ao gerenciamento de barreiras em segurança de processos"
          ],
          "limites": [
            "a fonte não detalha como demonstrar independência entre barreiras"
          ]
        },
        {
          "proposicao": "A remoção de uma barreira é apresentada como indevida, exceto se testes demonstrarem que as demais salvaguardas são adequadas e suficientes; em caso de vazamento de produto perigoso, medidas mitigadoras independentes devem ser postas em prática para evitar agravamento.",
          "trechos": [
            "E4d70a1f5507e385e:0:696"
          ],
          "condicoes": [
            "a exceção depende de testes demonstrando adequação e suficiência das demais salvaguardas",
            "as medidas mitigadoras mencionadas devem ser independentes"
          ],
          "limites": [
            "a fonte não informa quais testes nem critérios de suficiência",
            "não apresenta hierarquia formal de medidas de redução"
          ]
        },
        {
          "proposicao": "Os diagramas bow tie visualizam o sistema de barreiras e medidas mitigadoras, enquanto o processo HEMP é descrito como método estruturado para identificar ameaças, definir barreiras preventivas e mitigadoras para atingir ALARP, além de explicitar tarefas críticas, responsabilidades e medidas de desempenho para efetividade das barreiras.",
          "trechos": [
            "E4d70a1f5507e385e:696:1394",
            "E4d70a1f5507e385e:1394:2081"
          ],
          "condicoes": [
            "a efetividade das barreiras é condicionada à clareza das responsabilidades individuais e à execução disciplinada dos processos"
          ],
          "limites": [
            "a fonte descreve o método e sua integração com etapas da gestão de riscos, sem estabelecer exigência regulatória brasileira",
            "não detalha indicadores ou metas de desempenho"
          ]
        }
      ]
    },
    {
      "id": "E24925b1b9491e7b8",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No estudo relatado, o sistema informatizado da metodologia apresentou de forma sequencial a cadeia causal de cenários de risco, da causa inicial à consequência final, por integração automatizada de dados de operação, manutenção, inspeção e segurança.",
          "trechos": [
            "E24925b1b9491e7b8:0:698"
          ],
          "condicoes": [
            "resultado observado no sistema informatizado desenvolvido para suportar a metodologia"
          ],
          "limites": [
            "é um achado do estudo aplicado, não uma garantia geral para qualquer sistema",
            "a fonte não informa métricas de desempenho do sistema"
          ]
        },
        {
          "proposicao": "A metodologia aplicada mostrou-se útil, no caso estudado, para apoiar planejamento de manutenção, reuniões de análise de simultaneidade de serviços, liberação de permissão de trabalho, definição de contingenciamentos e retirada de operação de sistemas com cenários fora da região ALARP.",
          "trechos": [
            "E24925b1b9491e7b8:0:698",
            "E24925b1b9491e7b8:698:1397"
          ],
          "condicoes": [
            "uso associado a cenários de risco avaliados pela metodologia",
            "particularmente quando cenários estão fora da região ALARP"
          ],
          "limites": [
            "o texto expressa utilidade observada na aplicação, não regra universal",
            "não apresenta comparação com métodos alternativos"
          ]
        }
      ]
    },
    {
      "id": "E3962185badb7f822",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na metodologia descrita, os dados para o diagnóstico são majoritariamente adquiridos automaticamente de sistemas de operação, manutenção, inspeção e segurança, incluindo condição de equipamentos, inibição de intertravamentos e informações de salvaguardas; apenas pequena parte é inserida manualmente.",
          "trechos": [
            "E3962185badb7f822:0:689",
            "E3962185badb7f822:689:1387"
          ],
          "condicoes": [
            "aplicado a sistemas de suporte às operações de instalações de produção"
          ],
          "limites": [
            "a fonte não informa critérios de validação nem tratamento de inconsistências dos dados"
          ]
        },
        {
          "proposicao": "A seleção de cenários monitorados toma a APR quinquenal como documento de referência e inclui, na metodologia proposta, os cenários com severidade crítica ou catastrófica nas dimensões Pessoas, Meio Ambiente e Patrimônio.",
          "trechos": [
            "E3962185badb7f822:689:1387",
            "E3962185badb7f822:1387:2080"
          ],
          "condicoes": [
            "dependente do conteúdo da APR quinquenal",
            "restrito aos cenários classificados com severidade crítica ou catastrófica nas dimensões indicadas"
          ],
          "limites": [
            "o critério pertence à metodologia proposta na fonte",
            "não cobre explicitamente cenários de menor severidade"
          ]
        },
        {
          "proposicao": "Os elementos das salvaguardas preventivas e mitigadoras dos cenários monitorados são tratados como Elementos Críticos de Segurança Operacional, e o Bow Tie, do ponto de vista qualitativo, é descrito como ferramenta que explicita a lógica entre componentes do cenário acidental, combinações de eventos primários e falhas de barreiras que levam ao evento topo.",
          "trechos": [
            "E3962185badb7f822:1387:2080",
            "E3962185badb7f822:2080:2416"
          ],
          "condicoes": [
            "aplicado aos cenários monitorados na metodologia"
          ],
          "limites": [
            "a descrição do Bow Tie é qualitativa",
            "a fonte não fornece critérios quantitativos de confiabilidade ou disponibilidade das barreiras"
          ]
        }
      ]
    }
  ],
